ParameterPage paramPage = tools.getParameterPage();
responseModel  = paramPage.getString("pyResDataTransform");
primaryPageClass = paramPage.getString("pyClassName");
isExecuteOnDataPage =paramPage.getAsBoolean("pyExecuteOnDataPage");

isSameClass = true;
if(primaryPageClass != null && !primaryPageClass.equals("Code-Pega-List") && responseModel  != null && !responseModel.equals("")){
 if(!isExecuteOnDataPage) { 
     isSameClass = false;
    resultPageName = "pyDataSource"+ Thread.currentThread().getId() + System.nanoTime(); 
    resultPageName = resultPageName.replaceAll("-","_");
    paramPage.putString("pyPageName",resultPageName);

 }
}

ParameterPage paramPage = tools.getParameterPage();
savedInPegaVersionExists = tools.getParameterPage().isDefined("pySavedInPegaVersion");
if(!isSameClass && savedInPegaVersionExists){ //Get page messages and copy onto the data page. "savedInPegaVersionExists" created for backward compatibility. US-74635.
  if(tools.findPage(resultPageName).getMessagesAll() != null && !tools.findPage(resultPageName).getMessagesAll().trim().equals(""))
     tools.getPrimaryPage().addMessage(tools.findPage(resultPageName).getMessagesAll());
}

if(pega_rules_default.hasMessages(tools.getPrimaryPage())) {
  tools.getPrimaryPage().putString(".pyErrorPage.pyStatus","Fail");
  tools.getPrimaryPage().putString(".pyErrorPage.pyStatusMessage",tools.getPrimaryPage().getMessagesAll());
  ClipboardPage resultPage = tools.findPage(resultPageName);
  if(resultPage!=null){
    resultPage.putString(".pyErrorPage.pyStatus","Fail");
    resultPage.putString(".pyErrorPage.pyStatusMessage",tools.getPrimaryPage().getMessagesAll());
  }

}


ParameterPage dtParamPage = new ParameterPage();
java.util.Set keySet = paramPage.keySet();
java.util.Iterator paramItr = keySet.iterator();
if(paramPage.getString("pyPassCurrentParamPageForRespDT") != null && !paramPage.getString("pyPassCurrentParamPageForRespDT").equals("true")) {
         while(paramItr.hasNext()) {
            String paramName = (String)paramItr.next();
            if(paramName.toUpperCase().startsWith("PZ_RESDT")) {
                    String name = paramName.substring(9);
                   String value = paramPage.getString(paramName);
                  if(!"".equals(name))
                          dtParamPage.putString(name,value);
           }
       }
} else {
   dtParamPage = paramPage;
}
if(responseModel != null && responseModel.trim().length() != 0 ) {
  String dataSourceRecord = null;  
	dtParamPage.putParamValue("DataSource",resultPageName);
	tools.applyModel(myStepPage, dtParamPage , responseModel); 

}
